package hu.boltseged.auth;
import hu.boltseged.account.*; import org.junit.jupiter.api.Test; import org.springframework.security.crypto.password.PasswordEncoder; import java.math.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;
class AccountOnboardingTest {@Test void registrationUsesOnlyCredentialsAndSafeDefaults(){AccountRepository repo=mock(AccountRepository.class);PasswordEncoder encoder=mock(PasswordEncoder.class);when(repo.findByEmailIgnoreCase("customer@example.com")).thenReturn(Optional.empty());when(encoder.encode("StrongPassword123!")).thenReturn("hash");when(repo.save(any())).thenAnswer(i->i.getArgument(0));new AuthController(repo,encoder,"01234567890123456789012345678901").register(new AuthController.Register("customer@example.com","StrongPassword123!"));Account account=org.mockito.Mockito.mockingDetails(repo).getInvocations().stream().filter(i->i.getMethod().getName().equals("save")).map(i->(Account)i.getArgument(0)).findFirst().orElseThrow();assertEquals("CUSTOMER",account.getRole());assertTrue(account.isActive());assertEquals("FIXED",account.getPricingType());assertEquals(new BigDecimal("1000"),account.getPricingValue());assertNull(account.getCompanyName());verify(encoder).encode("StrongPassword123!");}}
